using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

// Existing inspect, stack and binary-choice consumers; these are incremental UI proofs.
public static class DungeonRestrictionPresentationValidation
{
    public static bool Running {get;private set;}
    public static string Output {get;private set;}
    [Serializable] sealed class Meta {public string folder,status;}
    sealed class Host:MonoBehaviour{}
    static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
    static Transform Root=>GameObject.Find("Canvas").transform;
    static TMPro.TextMeshProUGUI Rules=>Root.Find("InspectPanel/Rules").GetComponentInChildren<TMPro.TextMeshProUGUI>();
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static string Hash(string p){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    static ForgeSeatView Read(string p){File.AppendAllText(Output+"/input-hashes.tsv",p+"\t"+Hash(p)+"\n");return JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));}
    static void Clean(ForgeBattlefieldController ui){foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}var f=typeof(ForgeBattlefieldController).GetField("inspectHoverRevision",Hidden);f.SetValue(ui,(int)f.GetValue(ui)+1);}
    static void Inspect(ForgeBattlefieldController ui,ForgeCardView c){typeof(ForgeBattlefieldController).GetField("inspectOriginalState",Hidden).SetValue(ui,false);typeof(ForgeBattlefieldController).GetMethod("InspectIntegrated",Hidden).Invoke(ui,new object[]{c});}
    static void Click(Button b){var rect=(RectTransform)b.transform;var p=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,"Ray blocked "+b.name);ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,ExecuteEvents.pointerClickHandler);}
    public static void Run(){Check(Application.isPlaying&&!Running,"Play required");Running=true;Output=".tools/dungeon-paths-1006/restriction-ui/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output);File.WriteAllText(".tools/dungeon-paths-1006/restriction-ui/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/DungeonRestrictionPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.DungeonChoices.cs","Assets/Scripts/UI/ForgeBattlefieldController.AbilityFace.cs","Assets/Scripts/UI/ForgeBattlefieldController.ModifiedCharacteristics.cs","Tools/ForgeBridge/java/mtgb/bridge/ForgeCharacteristicDetails.java"}.Select(p=>p+"\t"+Hash(p)))+"\n");var go=new GameObject("DungeonRestrictionValidation");go.AddComponent<Host>().StartCoroutine(Guard(Exercise(),go));}
    static IEnumerator Guard(IEnumerator e,GameObject go){Exception error=null;while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){error=ex;break;}if(!more)break;if(current is IEnumerator child){yield return Nested(child,ex=>error=ex);if(error!=null)break;}else yield return current;}try{(e as IDisposable)?.Dispose();}catch(Exception ex){error??=ex;}File.WriteAllText(Output+"/result.txt",error==null?"PASS: native attack restriction blue and localized, original/current ray toggle and same-ID expiry both projections; exact dungeon room stack paragraph/name localization and unchanged unknown/ordinary branch; native one-candidate freecast card-window yes/no ray accept/decline with readonly/duplicate guards; tomb reentry helper identity. Existing UI consumers incremental, not new native/UI first or network proof.":"FAIL\n"+error);Running=false;UnityEngine.Object.Destroy(go);}
    static IEnumerator Nested(IEnumerator e,Action<Exception> fail){while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){fail(ex);break;}if(!more)break;if(current is IEnumerator child)yield return Nested(child,fail);else yield return current;}}
    static IEnumerator Exercise(){
        var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("DungeonBattlefield").AddComponent<ForgeBattlefieldController>();bool enabled=ui.enabled;ui.enabled=false;var module=EventSystem.current.currentInputModule;bool active=module!=null&&module.enabled;if(module!=null)module.enabled=false;string language=GamePreferences.Language;
        var meta=JsonUtility.FromJson<Meta>(File.ReadAllText(".tools/dungeon-paths-1006/current-expiry/mage-twisted-expiry-result.json"));Check(meta.status=="PASS","Restriction native failed");var reentry=JsonUtility.FromJson<Meta>(File.ReadAllText(".tools/dungeon-paths-1006/reentry-native/tomb-reenter-result.json"));Check(reentry.status=="PASS","Reentry native failed");var mage=JsonUtility.FromJson<Meta>(File.ReadAllText(".tools/dungeon-paths-1006/native/mage-runestone-result.json"));
        try{foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
            int rev=GamePreferences.Revision;bool changing=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float deadline=Time.realtimeSinceStartup+20;while((!GamePreferences.Ready||changing&&GamePreferences.Revision==rev)&&Time.realtimeSinceStartup<deadline)yield return null;Check(GamePreferences.Ready,"Locale not ready");
            string restriction=lang=="zh-CN"?"不能进行攻击。":lang=="ja-JP"?"は攻撃できない。":" can't attack.";
            foreach(string other in new[]{"","-other"}){
                var v=Read(meta.folder+"/attack-forbidden"+other+".json");ui.Present(null,v.seat,false,null,null,"");ui.Present(v,v.seat,false,null,null,"");yield return Frame();Clean(ui);var bear=v.players.SelectMany(p=>p.battlefield).Single(c=>c.name=="Grizzly Bears");Inspect(ui,bear);yield return Frame();Check(Rules.text.Contains("<color=#70BFFF>")&&Rules.text.Contains(restriction),"Restriction not blue/localized "+lang+" "+Rules.text);if(lang=="zh-CN"&&other==""){ScreenCapture.CaptureScreenshot(Output+"/cannot-attack.png");yield return Frame();}Click(Root.Find("InspectPanel/OriginalState").GetComponent<Button>());yield return Frame();Check(!Rules.text.Contains(restriction),"Printed state contains extrinsic restriction");var restored=Read(meta.folder+"/attack-restored"+other+".json");Check(restored.players.SelectMany(p=>p.battlefield).Single(c=>c.name=="Grizzly Bears").id==bear.id,"Restoration ID changed");ui.Present(restored,restored.seat,false,null,null,"");yield return Frame();Clean(ui);Inspect(ui,restored.players.SelectMany(p=>p.battlefield).Single(c=>c.id==bear.id));yield return Frame();Check(!Rules.text.Contains(restriction),"Same-ID restriction stale");
            }
            foreach(string sample in new[]{".tools/dungeon-paths-1006/mage-stack-first.json",".tools/undercity-paths-1006/stack-secret.json",".tools/undercity-paths-1006/stack-archive.json"}){
                var stack=Read(sample);ui.Present(stack,stack.seat,false,null,null,"");yield return Frame();Clean(ui);var item=stack.stackItems.First(c=>(c.source.currentType??"").Split(' ').Contains("Dungeon"));var source=item.source;string description=item.description;var method=typeof(ForgeBattlefieldController).GetMethod("AbilityEffectText",Hidden);string text=(string)method.Invoke(ui,new object[]{source,description});string original=source.originalRules.Replace("\\n","\n");string rule=System.Text.RegularExpressions.Regex.Replace(description,@"\s+\[Room: [^\r\n]*\]$","");string Normalize(string value)=>System.Text.RegularExpressions.Regex.Replace((source.name=="Undercity"?System.Text.RegularExpressions.Regex.Replace(value,@"\bArchive\b","Archives"):value).Trim(),@"\s+"," ");var lines=original.Split('\n');int line=Array.FindIndex(lines,l=>Normalize(l)==Normalize(rule));Check(line>=0,"Known actual dungeon paragraph absent");string first=GamePreferences.FeatureRules(new CardFeatureDefinition{cardName=source.name,description=original}).Replace("\\n","\n").Split('\n')[line];int separator=first.IndexOfAny(new[]{'—','―','～','〜'});Check(separator>=0,"Unknown localized separator: "+first);string name=first.Substring(0,separator).Trim();string expected=first+"\n["+(lang=="zh-CN"?"房间：":lang=="ja-JP"?"部屋：":"Room: ")+name+"]";Check(text==expected,"Room stack duplicate/wrong "+text);string changed=description.Replace(" — "," — Unknown ");Check((string)method.Invoke(ui,new object[]{source,changed})==changed,"Changed unknown paragraph falsely translated");var ordinary=new ForgeCardView{name="Unknown",id=42,currentType="Creature"};Check((string)method.Invoke(ui,new object[]{ordinary,"Unknown (42) - Exact unknown rule."})=="Exact unknown rule.","Ordinary branch changed");File.WriteAllText(Output+"/"+Path.GetFileNameWithoutExtension(sample)+"-"+lang+".txt",text);if(lang=="zh-CN"){ScreenCapture.CaptureScreenshot(Output+"/"+Path.GetFileNameWithoutExtension(sample)+".png");yield return Frame();}
            }
            foreach(string option in new[]{"ok","cancel"})foreach(bool acting in new[]{true,false}){var v=Read(mage.folder+"/freecast-choice.json");int calls=0,last=-1;ui.Present(null,v.request.seat,false,null,null,"");ui.Present(v,v.request.seat,acting,i=>{calls++;last=i;},null,"");yield return Frame();Clean(ui);int index=ui.OptionIndex(option);Check(index>=0,"Freecast candidate missing");var b=Root.GetComponentsInChildren<Transform>().Single(t=>t.name=="SelectionAction_"+index).GetComponent<Button>();Check(b.interactable==acting,"Binary permissions");if(acting){Click(b);Check(calls==1&&last==index&&!ui.TrySubmitPresentedOption(index,v.request.requestId),"Freecast exact/duplicate");}else{b.onClick.Invoke();Check(calls==0&&!ui.TrySubmitPresentedOption(index,v.request.requestId),"Readonly freecast submitted");}}
            var tomb=Read(reentry.folder+"/resolved-4.json");ui.Present(tomb,tomb.seat,false,null,null,"");yield return Frame();Clean(ui);var dungeon=tomb.players.SelectMany(p=>p.effectMarkers).Single(c=>c.markerKind=="dungeon");var old=Read(reentry.folder+"/resolved-1.json").players.SelectMany(p=>p.effectMarkers).Single(c=>c.markerKind=="dungeon");Check(dungeon.id!=old.id,"Tomb helper reused completed identity");Check(Root.GetComponentsInChildren<Transform>().Any(t=>t.name=="Card_"+dungeon.id)&&!Root.GetComponentsInChildren<Transform>().Any(t=>t.name=="Card_"+old.id),"Reentry helper stale/missing");File.AppendAllText(Output+"/steps.log",lang+" PASS\n");
        }}finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(language);if(module!=null)module.enabled=active;}
    }
}
#endif
